-- Adhunik ERP — Phase 10 Payroll Enhancement
begin;
alter table public.employees add column bank_name text,add column account_holder_name text,add column bank_account_number text,add column ifsc_code text;
alter table public.payroll_runs drop constraint payroll_runs_status_check;alter table public.payroll_runs add constraint payroll_runs_status_check check(status in('DRAFT','FINALIZED','REOPENED'));alter table public.payroll_runs add column reopened_by uuid references auth.users(id),add column reopened_at timestamptz,add column reopen_reason text,add constraint payroll_runs_reopen_metadata check(status<>'REOPENED'or(reopened_by is not null and reopened_at is not null and nullif(trim(reopen_reason),'')is not null));
alter table public.employee_monthly_payroll drop constraint employee_monthly_payroll_status_check;alter table public.employee_monthly_payroll add constraint employee_monthly_payroll_status_check check(status in('DRAFT','FINALIZED','REOPENED'));
create or replace function public.lock_finalized_payroll()returns trigger language plpgsql as $$begin if old.status='FINALIZED'and new.status<>'REOPENED'then raise exception'Finalized payroll is locked';end if;return new;end$$;
create or replace function public.reopen_payroll(p_run uuid,p_reason text)returns void language plpgsql security definer set search_path=''as $$declare snap jsonb;begin if not public.has_erp_permission('hr-payroll.monthly_payroll','EDIT')then raise exception'Monthly Payroll edit permission required';end if;if nullif(trim(p_reason),'')is null then raise exception'Reopen reason is required';end if;perform 1 from public.payroll_runs where id=p_run and status='FINALIZED'for update;if not found then raise exception'Finalized payroll not found';end if;select jsonb_agg(to_jsonb(p))into snap from public.employee_monthly_payroll p where payroll_run_id=p_run;insert into public.payroll_audit(payroll_run_id,event_type,old_value,reason)values(p_run,'PAYROLL_REOPENED',snap,trim(p_reason));update public.employee_monthly_payroll set status='REOPENED',updated_by=auth.uid(),updated_at=now()where payroll_run_id=p_run;update public.payroll_runs set status='REOPENED',reopened_by=auth.uid(),reopened_at=now(),reopen_reason=trim(p_reason),updated_at=now()where id=p_run;end$$;
create or replace function public.recalculate_payroll(p_run uuid)returns uuid language plpgsql security definer set search_path=''as $$declare r public.payroll_runs%rowtype;begin if not public.has_erp_permission('hr-payroll.monthly_payroll','EDIT')then raise exception'Monthly Payroll edit permission required';end if;select * into r from public.payroll_runs where id=p_run and status='REOPENED';if not found then raise exception'Reopened payroll not found';end if;update public.payroll_runs set status='DRAFT'where id=p_run;update public.employee_monthly_payroll set status='DRAFT'where payroll_run_id=p_run;perform public.prepare_payroll(r.month,r.year);update public.payroll_runs set status='REOPENED'where id=p_run;update public.employee_monthly_payroll set status='REOPENED'where payroll_run_id=p_run;insert into public.payroll_audit(payroll_run_id,event_type)values(p_run,'PAYROLL_RECALCULATED');return p_run;end$$;
create or replace function public.finalize_payroll(p_run uuid)returns void language plpgsql security definer set search_path=''as $$declare previous text;begin if not public.has_erp_permission('hr-payroll.monthly_payroll','EDIT')then raise exception'Monthly Payroll edit permission required';end if;select status into previous from public.payroll_runs where id=p_run and status in('DRAFT','REOPENED')for update;if not found then raise exception'Editable payroll not found';end if;if exists(select 1 from public.employee_monthly_payroll where payroll_run_id=p_run and eligibility_error is not null)then raise exception'Resolve all payroll eligibility errors';end if;update public.employee_monthly_payroll set status='FINALIZED',finalized_by=auth.uid(),finalized_at=now(),updated_by=auth.uid(),updated_at=now()where payroll_run_id=p_run;update public.payroll_runs set status='FINALIZED',finalized_by=auth.uid(),finalized_at=now(),updated_at=now()where id=p_run;insert into public.payroll_audit(payroll_run_id,event_type)values(p_run,case when previous='REOPENED'then'PAYROLL_REFINALIZED'else'PAYROLL_FINALIZED'end);end$$;
create or replace function public.update_payroll_variables(p_id uuid,p_percentage numeric,p_overtime numeric,p_adjustment numeric,p_reason text)returns void language plpgsql security definer set search_path=''as $$declare x public.employee_monthly_payroll%rowtype;begin if not public.has_erp_permission('hr-payroll.monthly_payroll','EDIT')then raise exception'Monthly Payroll edit permission required';end if;select * into x from public.employee_monthly_payroll where id=p_id and status in('DRAFT','REOPENED')for update;if not found then raise exception'Editable payroll not found';end if;if p_percentage<0 or p_overtime<0 or(p_adjustment<>0 and nullif(trim(p_reason),'')is null)then raise exception'Invalid payroll variables or missing adjustment reason';end if;update public.employee_monthly_payroll set crm_incentive_percentage=p_percentage,crm_incentive_amount=round(crm_eligible_amount*p_percentage/100,2),overtime_amount=p_overtime,adjustment_amount=p_adjustment,adjustment_reason=nullif(trim(p_reason),''),net_payable=round(attendance_salary+crm_eligible_amount*p_percentage/100+p_overtime+p_adjustment,2),updated_by=auth.uid(),updated_at=now()where id=p_id;insert into public.payroll_audit(payroll_run_id,payroll_id,event_type,old_value,new_value,reason)values(x.payroll_run_id,p_id,'PAYROLL_UPDATED',jsonb_build_object('percentage',x.crm_incentive_percentage,'overtime',x.overtime_amount,'adjustment',x.adjustment_amount),jsonb_build_object('percentage',p_percentage,'overtime',p_overtime,'adjustment',p_adjustment),p_reason);end$$;
revoke all on function public.reopen_payroll(uuid,text),public.recalculate_payroll(uuid)from public,anon;grant execute on function public.reopen_payroll(uuid,text),public.recalculate_payroll(uuid)to authenticated;
commit;
